-- 001_control_plane.sql (PostgreSQL production schema)
CREATE TABLE businesses (id text PRIMARY KEY, tenant_id text NOT NULL, name text NOT NULL, brand jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE content_jobs (id uuid PRIMARY KEY, business_id text NOT NULL REFERENCES businesses(id), content_item_id text, format text NOT NULL CHECK (format IN ('SHORT','LONG','BOTH')), current_state text NOT NULL, state_version integer NOT NULL DEFAULT 1, idempotency_key text NOT NULL, workflow_version text NOT NULL, brand_rule_version text NOT NULL, quality_policy_version text NOT NULL, created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL, UNIQUE (business_id,idempotency_key));
CREATE TABLE job_state_transitions (id uuid PRIMARY KEY, job_id uuid NOT NULL REFERENCES content_jobs(id), from_state text, to_state text NOT NULL, actor_type text NOT NULL, actor_id text, reason text, run_id text, occurred_at timestamptz NOT NULL, metadata jsonb NOT NULL DEFAULT '{}');
CREATE TABLE artifacts (artifact_id uuid PRIMARY KEY, business_id text NOT NULL REFERENCES businesses(id), content_job_id uuid REFERENCES content_jobs(id), logical_name text NOT NULL, version integer NOT NULL, content_hash text NOT NULL, storage_reference text NOT NULL, source text, created_at timestamptz NOT NULL, UNIQUE(business_id,logical_name,version), UNIQUE(business_id,artifact_id));
CREATE TABLE evidence_records (id uuid PRIMARY KEY, business_id text NOT NULL REFERENCES businesses(id), job_id uuid REFERENCES content_jobs(id), type text NOT NULL, source text, reference text, payload jsonb, payload_ref text, content_hash text, created_at timestamptz NOT NULL);

